window.TEXTP["76.17"] = [[["p","ВОПРОС № 3: НЕКОТОРЫЕ ЛЮДИ БЕРУТ ПОЧВУ С «МОГИЛЫ АЛЬ-ХУСЕЙНА» (ПРИ НАЛИЧИИ ТАКОЙ ВОЗМОЖНОСТИ) И ПИШУТ ЕЮ ИМЯ ПОКОЙНОГО, И ЧТО ОН ЗАСВИДЕТЕЛЬСТВОВАЛ ДВА СВИДЕТЕЛЬСТВА, И ПИШУТ РЯДОМ ИМЕНА ЧЛЕНОВ СЕМЬИ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ), А ЗАТЕМ КЛАДУТ ЭТУ НАДПИСЬ В ЕГО САВАН<sup class=\"fn\">503</sup>"],["n",[[503,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Так поступают (шииты) имамиты, как это пришло в \"Мифтах аль-карама\", 1/455-456». </i>"]]],["p","<b>См. «Ахкам аль-джанаиз», стр. 312; «Тальхис аль-Джанаиз», стр. 99.</b>"],["sep",""],["h2","ВОПРОС № 4: НЕКОТОРЫЕ ЛЮДИ ПИШУТ НА САВАНЕ РАЗЛИЧНЫЕ МОЛЬБЫ (ДУ′А)"],["p","<b>См. «Ахкам аль-джанаиз», стр. 312; «Тальхис аль-Джанаиз», стр. 98.</b>"],["sep",""],["h2","ВОПРОС № 5: РАЗУКРАШИВАНИЕ ПОХОРОННЫХ НОСИЛОК"],["p","<b>См. «аль-Ба′ис ′аля инкар аль-бида′ уаль хауадис», стр. 67; «Ахкам аль-джанаиз», 312; «Тальхис аль-Джанаиз», стр. 99.</b>"],["sep",""],["h2","ВОПРОС № 6: НЕКОТОРЫЕ ЛЮДИ НЕСУТ ФЛАГИ ПЕРЕД ПОХОРОННОЙ ПРОЦЕССИЕЙ"],["p","<b>См. «Ахкам аль-джанаиз», стр. 313; «Тальхис аль-Джанаиз», стр. 99.</b>"],["sep",""],["p","ВОПРОС № 7: НЕКОТОРЫЕ ЛЮДИ КЛАДУТ ЧАЛМУ НА ПОГРЕБАЛЬНЫЕ НОСИЛКИ, ЧТОБЫ УКАЗАТЬ НА ВЫСОКИЙ СТАТУС УМЕРШЕГО. ТО ЖЕ САМОЕ КАСАЕТСЯ ТЕХ, КТО КЛАДЁТ ТЮБЕТЕЙКУ ИЛИ ЦВЕТОЧНЫЙ ВЕНОК"],["p","<b>О нежелательности этого ясно сказал Ибн ′Абидин в «аль-Хашия», 1/806, и ученые, жившие до него. См. также «Ахкам аль-джанаиз», стр. 313; «Тальхис аль-Джанаиз», стр. 99.</b>"],["sep",""],["h2","ВОПРОС № 8: НЕКОТОРЫЕ ЛЮДИ НЕСУТ ПЕРЕД ПОГРЕБАЛЬНЫМИ НОСИЛКАМИ ВЕНКИ, ЦВЕТЫ ИЛИ ФОТОГРАФИЮ УМЕРШЕГО."],["p","<b>См. «Ахкам аль-джанаиз», стр. 313; «Тальхис аль-Джанаиз», стр. 99.</b>"],["sep",""],["p","ВОПРОС № 9: НЕКОТОРЫЕ ЛЮДИ, КОГДА ПОГРЕБАЛЬНЫЕ НОСИЛКИ ВЫНОСЯТ ИЗ ДОМА, ПРИНОСЯТ В ЖЕРТВУ ЯГНЕНКА ВОЗЛЕ ДВЕРИ. А НЕКОТОРЫЕ ДУМАЮТ, ЧТО ЕСЛИ ЭТОГО НЕ СДЕЛАТЬ, ТО В БЛИЖАЙШЕЕ ВРЕМЯ УМРУТ ЕЩЕ ТРИ ЧЕЛОВЕКА ИЗ ЭТОЙ СЕМЬИ"],["p","<b>См. «аль-Ибда′ фи мадарр аль-ибтида′», стр. 114; «Ахкам аль-джанаиз», стр. 313; «Тальхис аль-Джанаиз», стр. 99.</b>"],["sep",""],["p","ВОПРОС № 10: НЕКОТОРЫЕ ЛЮДИ ВЕДУТ ПЕРЕД ПОГРЕБАЛЬНЫМИ НОСИЛКАМИ ЯГНЕНКА И НЕСУТ ХЛЕБ. ПОСЛЕ ПОХОРОН ОНИ РЕЖУТ ЭТОГО ЯГНЕНКА И РАЗДАЮТ ЕГО МЯСО ВМЕСТЕ С ХЛЕБОМ"],["p","<b>См. «аль-Мадхаль», 3/266-267; «Ахкам аль-джанаиз», стр. 313; «Тальхис аль-Джанаиз», стр. 99.</b>"],["sep",""],["h2","ВОПРОС № 11: НЕКОТОРЫЕ ЛЮДИ ДУМАЮТ, ЧТО ЕСЛИ ПОКОЙНЫЙ БЫЛ ПРАВЕДНЫМ ЧЕЛОВЕКОМ, ТО ЕГО НОСИЛКИ ОБЯЗАТЕЛЬНО БУДУТ ЛЕГКИМИ"],["p","<b>См. «Ахкам аль-джанаиз», стр. 313; «Тальхис аль-Джанаиз», стр. 99.</b>"],["sep",""],["p","ВОПРОС № 12: НЕКОТОРЫЕ ЛЮДИ ПО ХОДУ СЛЕДОВАНИЯ ПОХОРОННОЙ ПРОЦЕССИИ РАЗДАЮТ МИЛОСТЫНЮ, И ТАКЖЕ ОНИ ПОЛИВАЮТ ЛАКРИЦУ, ЛИМОНЫ И Т. П."],["p","<b>См. «Ахкам аль-джанаиз», стр. 313; «Тальхис аль-Джанаиз», стр. 99.</b>"],["sep",""],["p","ВОПРОС № 13: НЕКОТОРЫЕ ЛЮДИ СЧИТАЮТ, ЧТО ВО ВРЕМЯ ПЕРЕНОСА ПОГРЕБАЛЬНЫХ НОСИЛОК НУЖНО ПО ОЧЕРЕДИ БРАТЬСЯ ЗА КАЖДУЮ ИЗ ЧЕТЫРЕК РУЧЕК НОСИЛОК И СДЕЛАТЬ ПРИ КАЖДОМ ТАКОМ ПОДХОДЕ ПО ДЕСЯТЬ ШАГОВ<sup class=\"fn\">504</sup>"],["n",[[504,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Некоторые знатоки фикха аргументируют в этом вопросе следующим хадисом: </i><b><i>\"Если человек пронесёт погребальные носилки сорок шагов, то ему будет прощено сорок тяжких грехов\". </i></b><i>Автор книги «аль-Бахр ар-Раик» передал его, сославшись на книгу «аль-Бадаи′». А в «Шарх аль-манийя» сказано: «Его передал Абу Бакр ан-Наджжад», как это пришло в «аль-Хашия», 1/833. Так они передают этот хадис друг от друга, ничего не говоря об его достоверности. На самом же деле, он не является достоверным, так как среди его передатчиков - ′Али ибн Аби Сара, который был слабым. А этот хадис вообще был отвергнут, когда он передал его, как об этом сказал аз-Захаби. Именно поэтому в книге «аль-Джами′ ас-сагыр» мы назвали его выдуманным. Но вместе с этим, данный хадис вообще никак не указывает на это новшество. Обрати же на это внимание!». </i>"]]]],[["p","<b>См. «Ахкам аль-джанаиз», стр. 313; «Тальхис аль-Джанаиз», стр. 99.</b>"],["sep",""],["h2","ВОПРОС № 14: НЕКОТОРЫЕ ЛЮДИ СЧИТАЮТ, ЧТО НЕОБХОДИМО НЕСТИ ПОГРЕБАЛЬНЫЕ НОСИЛКИ МЕДЛЕННО"],["p","<b>См. «аль-Ба′ис ′аля инкар аль-бида′ уаль хауадис», стр. 51, 67; «Зад уль-ма′ад», 1/299; «аль-Амру биль иттиба′», стр. 251, ас-Суюты; «Ахкам аль-джанаиз», стр. 314; «Тальхис аль-Джанаиз», стр. 99.</b>"],["p","<b>Сказал наш шейх (аль-Альбани), да помилует его Всевышний Аллах, в «Ахкам аль-джанаиз» и в «Тальхис аль-Джанаиз», стр. 40:</b>"],["p","«Сказал ан-Науауи в «аль-Маджму′», 5/271: <i>«Ученые единогласны в том, что желательно нести похоронные носилки быстро, кроме как если есть опасность того, что тело покойного упадет, или с ним случится что-то еще. В этом случае следует нести их медленно». </i>"],["p","Я скажу: явный смысл этого хадиса указывает на обязательность<sup class=\"fn\">505</sup>. И об этом сказал Ибн Хазм, 5/154-155. И мы не знаем довода, который переводил бы этот приказ с обязательности на желательность. Сказал Ибн уль-Каййим в «Зад уль-ма′ад»: <i>«Когда же люди идут, (неся погребальные носилки), медленным шагом, то это является порицаемым новшеством и противоречит Сунне. К тому же это содержит в себе уподобление иудеям». </i>"],["n",[[505,"Так как в хадисе пришёл приказ: <b><i>«Спешите с погребальными носилками…». </i></b>"]]],["sep",""],["h2","ВОПРОС № 15: СТОЛПОТВОРЕНИЕ ВОКРУГ ПОГРЕБАЛЬНЫХ НОСИЛОК<sup class=\"fn\">506</sup>"],["n",[[506,"Здесь в примечаниях шейх аль-Альбани привел следующее сообщение: <i>«Катада рассказывал: «Однажды я присутствовал на похоронах, где также присутствовал Абу ас-Сиууар Хурейс ибн Хассан аль-′Адауи. Люди столпились вокруг погребальных носилок, а Абу ас-Сиууар сказал: \"Вы считаете себе лучше сподвижников Мухаммада (да благословит его Аллах и приветствует)?! Если один из них видел место, он хватался за носилки (и нёс тело), а в противном случае он отходил и никому не причинял неудобства\"».</i>"]]],["p","<b>См. «аль-Мухалля», 5/178, Ибн Хазм; «Ахкам аль-джанаиз», стр. 314; «Тальхис аль-Джанаиз», стр. 99.</b>"],["sep",""],["h2","ВОПРОС № 16: ЧРЕЗМЕРНОЕ ОТДАЛЕНИЕ ОТ ПОГРЕБАЛЬНЫХ НОСИЛОК"],["p","<b>См. «аль-Ба′ис ′аля инкар аль-бида′ уаль хауадис», стр. 67; «Ахкам аль-джанаиз», стр. 314; «Тальхис аль-Джанаиз», стр. 99.</b>"],["sep",""],["h2","ВОПРОС № 17: РАЗГОВОРЫ ВО ВРЕМЯ ПРОВОДОВ ПОХОРОННОЙ ПРОЦЕССИИ"],["p","<b>См. «Хашия Ибн ′Абидин», 1/810. Речь идёт о том, что не следует громким голосом поминать Аллаха во время проводов похоронной процессии, и точно также не следует болтать друг с другом. См. также «Ахкам аль-джанаиз», стр. 314; «Тальхис аль-Джанаиз», стр. 99.</b>"],["p","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «Ахкам аль-джанаиз», стр. 92, и в «Тальхис аль-Джанаиз», стр. 39-40:</b>"],["p","«Также сюда относится<sup class=\"fn\">507</sup> громкое поминание Аллаха перед похоронной процессией, ибо это является новшеством. Кайс ибн ′Аббад сказал: <i>«Сподвижникам пророка (да благословит его Аллах и приветствует) не нравилось, чтобы возле похоронных процессией поднимали голос». </i>Передали аль-Бейхакы, 4/74; Ибн уль-Мубарак в «аз-Зухд», 83; Абу Ну′айм, 9/58. Все передатчики этого сообщения являются крепкими."],["n",[[507,"То есть к тому, что запрещено во время похорон."]]]],[["p","К тому же в этом есть уподобление христианам, ибо они поднимают голоса (в таких случаях), читая что-то из Евангелия или своих поминаний, сопровождая это протяжным и грустным пением. А еще более скверное дело заключается в том, когда похоронные процессии провожают с музыкальными инструментами и грустными мелодиями. Так делают в некоторых исламских странах, подражая иноверцам. А Аллах – Тот, к Кому обращаются за помощью!"],["p","Сказал ан-Науауи, да помилует его Всевышний Аллах, в «аль-Азкар», стр. 203:"],["p","<i>«Знай, что правильнее всего поступать так, как поступали наши праведные предшественники (да будет доволен ими Аллах), которые хранили молчание, когда сопровождали погребальные носилки, не читая вслух Коран, не поминая Аллаха и не произнося никаких иных слов. Смысл этого очевиден, ибо молчание помогает человеку успокоиться и сосредоточиться на размышлениях обо всём связанном с похоронами, что и является необходимым в такие моменты. Это и есть истина! Если же многие люди станут вести себя по-иному, пусть это ни в коей мере не вводит тебя в заблуждение. Некогда Абу ‘Али аль-Фудейль ибн ‘Ийад, да помилует его Аллах, произнёс слова, смысл которых заключается в следующем: неуклонно следуй правильными путями, и тебе не повредит то, что людей, которые следуют ими, найдётся немного; ни в коем случае не следуй путями заблуждения и не обольщайся многочисленностью тех, кто находит на этих путях свою гибель.</i>"],["p","<i>В «Сунан» аль-Бейхакы приводится то, что подтверждает необходимость того, о чём было сказано мною выше</i><sup class=\"fn\">508</sup><i>. Что же касается действий невежд, которые в Дамаске и других местах вслух читают Коран во время похорон, протяжно произнося слова и изменяя их произношение, то, по мнению всех ученых, это является запретным. В книге «Адаб аль-курра’» я указал на запретность подобных действий, равно как и на нечестивость тех, кто может выразить этому порицание, но не делает этого, а за помощью следует обращаться к Аллаху».</i>"],["n",[[508,"Речь идёт о словах Кайса ибн ′Аббада, которые были приведены выше."]]],["sep",""],["h3","<b>Сказал автор книги «Та′алим аль-ислям» (Устои ислама), стр. 252-253:</b>"],["p","«Нет ничего греховного в том, чтобы (громко) произносить «ля иляха илля Ллах», «Аллаху акбар», «Субхана Ллах» перед похоронной процессией, или же, например, просить благословения для пророка (да благословит его Аллах и приветствует), ибо это станет девизом умершего. И если мы оставим это, то мы как будто бы пренебрежительно отнеслись к нему и покусились на него и его наследников. И если кто-то скажет об обязательности (такого поминания), то он не уйдет далеко от истины!»."]],[["p","<b>Сказал наш шейх аль-Альбани, да помилует его Аллах, опровергая эти слова в своей книге «ад-Да′ифа», 1/606-607: </b>"],["p","«Во-первых, это является новшеством, внесенным в религию и не имеющим никакой основы в Сунне. Во-вторых, об этом не говорил никто из имамов. И я удивляюсь этим поздним ученым, которые запрещают искателю знаний следовать за достоверным хадисом, говоря, что этот хадис противоречит мазхабу, но при этом они высказывают свои мнения там, где им нет места, ибо эти их мнения противоречат Сунне и противоречат тому, что сказали имамы, за которыми они (как они говорят) следуют."],["p","Клянусь Аллахом, я уже будто склоняюсь к мнению тех поздних ученых, которые говорят о том, что двери иджтихада закрыты<sup class=\"fn\">509</sup>, когда вижу вот такие высказывания, на которые нет никакого религиозного довода. И те, кто высказал эти мнения, даже не следуют в этом за каким-нибудь имамом. И вот когда эти слепые последователи принимаются высказывать свои личные мнения, то они чаще ошибаются, чем бывают правы. Они больше нарушают порядок, чем исправляют ситуацию. А Аллах – Тот, к Кому обращаются за помощью!»."],["n",[[509,"То есть они говорят, что в наши дни никто не имеет права извлекать постановления из религиозных текстов, а должен только слепо следовать за более ранними учеными."]]],["sep",""],["p","ВОПРОС № 18: НЕКОТОРЫЕ ЛЮДИ ИДУТ ПОЗАДИ ПОХОРОННОЙ ПРОЦЕССИИ И ГРОМКО ПОМИНАЮТ АЛЛАХА, ПРОИЗНОСЯТ ЕГО ИМЕНА, ИЛИ ЖЕ ОНИ ЧИТАЮТ ПОЭМУ «БУРДА» ИЛИ «АД-ДАЛЯИЛЬ»"],["p","<b>См. «ас-Сунан уаль мубтада′ат», стр 67, Мухаммад ибн Ахмад аш-Шукайри; «Ахкам аль-джанаиз», стр. 314; «Тальхис аль-Джанаиз», стр. 100.</b>"],["sep",""],["p","ВОПРОС № 19: НЕКОТОРЫЕ ЛЮДИ ИДУТ ПОЗАДИ ПОХОРОННОЙ ПРОЦЕССИИ И ГОВОРЯТ: «ПРЕВЕЛИК АЛЛАХ! ПРЕВЕЛИК АЛЛАХ! Я СВИДЕТЕЛЬСТВУЮ, ЧТО АЛЛАХ ОЖИВЛЯЕТ И УМЕРЩВЛЯЕТ, И ОН – ЖИВОЙ И НЕ УМИРАЕТ. ПРЕЧИСТ ТОТ, КТО ВОЗВЕЛИЧИЛСЯ ПОСРЕДСТВОМ МОЩИ И ВЕЧНОСТИ, И ПОКОРИЛ СВОИХ РАБОВ ЧЕРЕЗ СМЕРТЬ И ИСЧЕЗНОВЕНИЕ»"],["p","<b>См. «Ахкам аль-джанаиз», стр. 314; «Тальхис аль-Джанаиз», стр. 100.</b>"],["sep",""],["p","ВОПРОС № 20: НЕКОТОРЫЕ ЛЮДИ ИДУТ ПОЗАДИ ПОХОРОННОЙ ПРОЦЕССИИ И ГРОМКО КРИЧАТ: «ПРОСИТЕ ДЛЯ НЕГО ПРОЩЕНИЯ, И ПУСТЬ АЛЛАХ ПРОСТИТ ВАС!» И Т. П."],["p","<b>См. «аль-Мадхаль», 2/221; «аль-Ибда′», стр. 113; «аль-Амр биль иттиба′», 254; «Ахкам аль-джанаиз», стр. 314; «Тальхис аль-Джанаиз», стр. 100.</b>"],["sep",""],["p","ВОПРОС № 21: НЕКОТОРЫЕ ЛЮДИ, ПРОХОДЯ МИМО МОГИЛЫ ПРАВЕДНОГО ЧЕЛОВЕКА ИЛИ ДОРОЖНОГО ПЕРЕКРЁСТКА, ГРОМКО КРИЧАТ: «АЛЬ-ФАТИХА»"],["p","<b>См. «Ахкам аль-джанаиз», стр. 314; «Тальхис аль-Джанаиз», стр. 100.</b>"],["sep",""],["p","ВОПРОС № 22: НЕКОТОРЫЕ ЛЮДИ, ВИДЯ ПОХОРОННУЮ ПРОЦЕССИЮ, ГОВОРЯТ: «ВСЯ ХВАЛА АЛЛАХУ, КОТОРЫЙ НЕ СДЕЛАЛ МЕНЯ ИЗ ЧИСЛА УМЕРШИХ!»"],["p","<b>См. «Ахкам аль-джанаиз», стр. 315; «Тальхис аль-Джанаиз», стр. 100.</b>"],["sep",""]],[["p","ВОПРОС № 23: НЕКОТОРЫЕ ЛЮДИ ДУМАЮТ, ЧТО ЕСЛИ НА ПОГРЕБАЛЬНЫХ НОСИЛКАХ НЕСУТ ПРАВЕДНОГО ЧЕЛОВЕКА, ТО ЭТИ НОСИЛКИ САМИ ПО СЕБЕ ОСТАНАВЛИВАЮТСЯ, КОГДА ПРОХОДЯТ МИМО МОГИЛЫ КАКОГО-НИБУДЬ «СВЯТОГО», ДАЖЕ ЕСЛИ НЕСУЩИЕ ИХ НЕ ХОТЕЛИ ОСТАНАВЛИВАТЬСЯ"],["p","<b>См. «Ахкам аль-джанаиз», стр. 315; «Тальхис аль-Джанаиз», стр. 100.</b>"],["sep",""],["p","ВОПРОС № 24: НЕКОТОРЫЕ ЛЮДИ, ВИДЯ ПОХОРОННУЮ ПРОЦЕССИЮ, ГОВОРЯТ: «ЭТО – ТО, ЧТО ОБЕЩАЛИ НАМ АЛЛАХ И ЕГО ПОСЛАННИК. ПРАВДУ СКАЗАЛ АЛЛАХ И ЕГО ПОСЛАННИК. О АЛЛАХ! ПРИБАВЬ НАМ ВЕРЫ И ПОКОРНОСТИ!»<sup class=\"fn\">510</sup>"],["n",[[510,"То есть в самих этих словах нет ничего греховного. Эти слова являются благой мольбой, но проблема в том, что некоторые авторы религиозной литературы говорят, что наша религия установила эти слова как желательные в такой-то конкретный момент, и еще относят это к пророку, да благословит его Аллах и приветствует, возводя на него навет. Именно поэтому автор (да помилует его Аллах) и называет подобное новшеством и заблуждением."]]],["p","<b>См. «Ахкам аль-джанаиз», стр. 315; «Тальхис аль-Джанаиз», стр. 100.</b>"],["sep",""],["h2","ВОПРОС № 25: НЕКОТОРЫЕ ЛЮДИ ПРОВОЖАЮТ ПОХОРОННУЮ ПРОЦЕССИЮ ВМЕСТЕ С КУРИЛЬНИЦАМИ<sup class=\"fn\">511</sup>"],["n",[[511,"Курильница - сосуд, предназначенный для сжигания ладана или духов в твердой форме. Среди русскоязычных мусульман еще закрепилось такое название как «бахурница»."]]],["p","<b>См. «Ахкам аль-джанаиз», стр. 315; «Тальхис аль-Джанаиз», стр. 100.</b>"],["sep",""],["p","ВОПРОС № 26: НЕКОТОРЫЕ ЛЮДИ, КОГДА НЕСУТ ПОХОРОННЫЕ НОСИЛКИ К МЕСТУ ПОГРЕБЕНИЯ, ПО ПУТИ СОВЕРШАЮТ С НИМИ ОБХОД ВОКРУГ МОГИЛ «СВЯТЫХ» ЛЮДЕЙ"],["p","<b>См. «Ахкам аль-джанаиз», стр. 315; «Тальхис аль-Джанаиз», стр. 100.</b>"],["sep",""],["p","ВОПРОС № 27: НЕКОТОРЫЕ ЛЮДИ, КОГДА НЕСУТ ПОХОРОННЫЕ НОСИЛКИ К МЕСТУ ПОГРЕБЕНИЯ, СОВЕРШАЮТ С НИМИ СЕМИКРАТНЫЙ ОБХОД ВОКРУГ КААБЫ<sup class=\"fn\">512</sup>"],["n",[[512,"Речь идёт о тех, кого хоронят в Мекке."]]],["p","<b>См. «аль-Мадхаль», 2/227; «Ахкам аль-джанаиз», стр. 315; «Тальхис аль-Джанаиз», стр. 100.</b>"],["sep",""],["h2","ВОПРОС № 28: ОБЪЯВЛЕНИЕ О ПОХОРОНАХ У ВОРОТ МЕЧЕТИ"],["p","<b>См. «аль-Мадхаль», 2/221, 262-263; «Ахкам аль-джанаиз», стр. 315; «Тальхис аль-Джанаиз», стр. 100.</b>"],["sep",""],["p","ВОПРОС № 29: НЕКОТОРЫЕ ЛЮДИ<sup class=\"fn\">513</sup> ЗАНОСЯТ УМЕРШЕГО ЧЕРЕЗ «ВРАТА МИЛОСТИ» В МЕЧЕТЬ АЛЬ-АКСА, А ЗАТЕМ КЛАДУТ ЕГО МЕЖДУ ВОРОТАМИ И СКАЛОЙ, ПОСЛЕ ЧЕГО ВОКРУГ СОБИРАЮТСЯ НЕКОТОРЫЕ ШЕЙХИ И ЧИТАЮТ РАЗЛИЧНЫЕ ПОМИНАНИЯ АЛЛАХА (АЗКАРЫ)"],["n",[[513,"Здесь речь идёт о тех, кого хоронят в Иерусалиме."]]],["p","<b>См. «Ахкам аль-джанаиз», стр. 315; «Тальхис аль-Джанаиз», стр. 100.</b>"],["sep",""],["p","ВОПРОС № 30: ОПЛАКИВАНИЕ УМЕРШЕГО, КОГДА ТЕЛО ПРИНОСЯТ В МЕЧЕТЬ ДО МОЛИТВЫ ИЛИ ПОСЛЕ МОЛИТВЫ, А ТАКЖЕ ОПЛАКИВАНИЕ ВОЗЛЕ МОГИЛЫ, КОГДА ЧЕЛОВЕКА УЖЕ ПОХОРОНИЛИ<sup class=\"fn\">514</sup>"],["n",[[514,"Естественно, речь не идёт о том, кто просто заплакал из-за грусти или переживаний за умершего. Речь идёт о тех, кто превратил этот плач в некий обряд похорон. Эти люди плачут не из-за того, что им грустно или печально, и они не могут сдержать слез, а просто из-за того, что считают это необходимым обрядом и частью религии."]]]],[["p","<b>См. «аль-Ибда′», 124-125; «Ахкам аль-джанаиз», стр. 315; «Тальхис аль-Джанаиз», стр. 100.</b>"],["sep",""],["p","ВОПРОС № 31: ПОСТОЯННАЯ ПЕРЕВОЗКА ПОГРЕБАЛЬНЫХ НОСИЛОК НА АВТОМОБИЛЯХ И СОПРОВОЖДЕНИЕ ПОХОРОННОЙ ПРОЦЕССИИ НА АВТОМОБИЛЯХ<sup class=\"fn\">515</sup>"],["n",[[515,"Речь идёт о тех, кто отказывается идти пешком и нести погребальные носилки на руках, даже если кладбище находится рядом, и это не составляет никакого труда. Ведь во времена пророка (да благословит его Аллах и приветствует) и предшественников носилки носили на руках, а не на верховых животных. Если же кладбище, например, находится очень далеко, то нет ничего греховного в использовании автомобилей. А Аллах знает лучше! Но, впрочем, сам шейх (да воздаст ему Аллах благом) разъяснит этот вопрос подробнее."]]],["p","<b>См. «Ахкам аль-джанаиз», стр. 315; «Тальхис аль-Джанаиз», стр. 100.</b>"],["p","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «Ахкам аль-джанаиз», стр. 99-100; и в «Тальхис аль-Джанаиз», стр. 41-42:</b>"],["p","«Что касается перевозки погребальных носилок на телеге или автомобиле, которые специально предназначены для похоронных процессий. И при этом люди, провожающие похоронную процессию, также едут на автомобиле. Подобное не является узаконенным по многим причинам:"],["p","<b>Во-первых</b>, это относится к обычаям неверующих. Утверждено в шариате, что запрещено подражать их обычаям. На эту тему пришло очень много хадисов. Я привёл их вместе с источниками в своей книге «Хиджаб мусульманки в свете Корана и Сунны». Некоторые хадисы повелевают и побуждают противоречить им в их поклонениях, одеяниях и обычаях. А некоторые передают нам действия пророка (да благословит его Аллах и приветствует), который противоречил им в этом. Если человек желает ознакомиться с этими хадисами, он может вернуться к этой книге."],["p","<b>Во-вторых</b>, это является новшеством в поклонении и противоречит Сунне, связанной с переноской похоронных носилок. И такие новшества являются заблуждением по единогласному мнению."],["p","<b>В-третьих</b>, это лишает людей той цели, из-за которой было узаконено нести и провожать похоронную процессию, а это – напоминание о Последней обители. Об этом прямо сказал посланник Аллаха (да благословит его Аллах и приветствует): <b><i>«Следуйте за похоронной процессией, ибо это напомнит вам о Последней обители». </i></b>"],["p","Я скажу: перевозка похоронных носилок на автомобиле в таком виде лишает людей этой почетной цели либо целиком, либо частично. Для разумного человека очевидно, что переноска тела на шеях, когда люди видят тех, кто провожает похоронные носилки и несёт их на себе, более сильно напоминает и увещевает, чем если похоронные носилки везут на автомобилях. Я не перейду границы, если скажу, что европейцы решили перевозить тела умерших на автомобилях из-за того, что боятся смерти и всего, что напоминает о ней, потому что они отдали предпочтение материальному миру и проявили неверие в Последнюю обитель."]],[["p","<b>В-четвертых</b>, это сильная причина уменьшения количества провожающих похоронную процессию и тех, кто желает обрести эту награду. Ведь не каждый человек может нанять машину, чтобы проводить похоронную процессию."],["p","<b>В-пятых</b>, подобное не имеют никакого сходства (ни далекого, ни близкого) с тем, что известно от пречистого и легкого шариата, который далёк от формализма, особенно в этом опасном вопросе – вопросе смерти."],["p","Я говорю истину: если бы в этом новшестве не было ничего плохого, кроме этого, то и этого было бы достаточно для того, чтобы его отвергнуть. А что сказать о других отрицательных последствиях и противоречиях Сунне, которые я даже не упомянул?!»."],["sep",""],["p","<b>Также наш шейх, да помилует его Всевышний Аллах, указал на одно из чудес пророка (да благословит его Аллах и приветствует), связанное с людьми, которые будут передвигаться на автомобилях и приходить к мечетям для проводов похоронных процессий, и будут оставаться в своих автомобилях перед мечетями, оставляя молитву. Он сказал в примечаниях к хадису со слов ′Абдуллаха ибн ′Амра в «Сахих Мауарид аз-замаан», 2/47, после хадиса № 1215-1454</b><sup class=\"fn\">516</sup><b>:</b>"],["n",[[516,"В этом хадисе сказано: <b><i>«В конце (существования) моей общины появятся мужчины, которые будут ездить на седлах, подобных седлам (ваших верблюдов), и будут останавливаться возле дверей мечетей. Их женщины будут одетыми, хотя (в действительности) будут нагими, а на их головах будет что-то подобное тощим верблюжьим горбам. Проклинайте их, ибо, поистине, они – проклятые! И если бы после вас была другая община, то ваши женщины прислуживали бы им, как (сейчас) женщины из числа предшествующих общин прислуживают вам!». </i></b>Этот хадис передали Ибн Хиббан в «Сахихе» и аль-Хаким, который сказал: <i>«Хадис достоверный в соответствии с условиями Муслима».</i>"]]],["p","«Если ты понял это, то ты поймешь (с соизволения Аллаха), что пророк (да благословит его Аллах и приветствует) указывает на эти средства передвижения, которые были изобретены в наше время. Речь идёт об автомобилях. Ведь, поистине, они – мягкие и удобные, подобно седлам на верблюдах."],["p","Таким образом, в этом хадисе сообщение о мужчинах, которые будут передвигаться на автомобилях и останавливаться возле дверей мечетей. Клянусь Аллахом, поистине, это правдивое пророческое известие, которое мы наблюдаем каждую пятницу, когда машины скапливаются перед мечетями так, что широкая дорога становится тесной. Из этих машин выходят мужчины, чтобы присутствовать на пятничной молитве, а большинство из них вообще не совершает пять обязательных молитв, или, как минимум, не совершает их в мечетях. Они будто бы довольствуются только лишь совершением одной пятничной молитвы, именно поэтому в пятницу их количество (в мечетях) возрастает. Они останавливают свои автомобили перед мечетями и на них не видно следов молитвы. Следов молитвы не видно в их отношении к женам и дочерям. Они точно соответствуют словам пророка (да благословит его Аллах и приветствует): <b><i>«Их женщины будут одетыми, хотя (в действительности) будут нагими».</i></b>"]],[["p","Также существует и другое явление, которое полностью соответствует этому хадису. В последнее время мы видим, как похоронные процессии сопровождают на автомобилях. В этих автомобилях сидят люди, у которых нет доли (в Последней Жизни), так как они богаты, изнеженны роскошью и относятся к числу оставляющих молитву. Когда автомобили останавливаются возле мечети, а тело покойного заносят в мечеть, чтобы совершить над ним заупокойную молитву, эти изнеженные роскошью люди остаются в своих автомобилях перед мечетью. Некоторые же выходят из автомобилей, чтобы проводить взором покойника, которого несут на кладбище, проявляя всеобщее лицемерие и заискивание, а не желая поклонения Аллаху и вспоминания Последней Жизни<sup class=\"fn\">517</sup>. А Аллах – Тот, к Кому надлежит обращаться за помощью!"],["n",[[517,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Также по радио и в других местах они говорят: «Покойный прибыл в своё последнее пристанище». Это, как минимум, неверие в словах. И меня очень сильно удивляет, когда ведущие из числа мусульман используют эту фразу, ведь они знают, что могила – это не последнее пристанище, а всего лишь временный промежуток между ближней жизнью и Последней обителью, после чего последует воскрешение, а затем уже последнее пристанище. Всевышний Аллах сказал: </i><b>«Одна часть людей окажется в Раю, а другая часть окажется в Пламени». </b><i>(Сура «аш-Шура», аят 7). Также Аллах сказал о второй группе: </i><b>«Их пристанищем будет Огонь». </b><i>(Сура «Фуссылят», аят 24). А эту фразу среди людей мог распространить только неверующий безбожник, после чего мусульмане, которые пребывают в сильной и удивительной беспечности, стали подражать ему. </i><b>«Но есть ли среди вас вспоминающие?». </b><i>(Сура «аль-Камар», аят 17)». </i>"]]],["p","Таково мое мнение в разъяснении этого хадиса. Если я оказался прав, то это от Аллаха, а если я ошибся, то это от меня. И только Всевышнего Аллаха я прошу, чтобы Он простил мои проступки и грехи, которые у меня, несомненно, имеются»."],["sep",""],["h2","ВОПРОС № 32: ПЕРЕВОЗКА НЕКОТОРЫХ ПОКОЙНЫХ НА ВОЕННЫХ ТЕЛЕЖКАХ"],["p","<b>См. «Ахкам аль-джанаиз», стр. 315; «Тальхис аль-Джанаиз», стр. 100.</b>"],["sep",""],["h2","ГЛАВА № 5 – НОВШЕСТВА, СВЯЗАННЫЕ С ПОГРЕБАЛЬНОЙ МОЛИТВОЙ (САЛЯТ АЛЬ-ДЖАНАЗА)"],["p","ВОПРОС № 1: СОВЕРШЕНИЕ ПОГРЕБАЛЬНОЙ МОЛИТВЫ ЗА МУСУЛЬМАН, КОТОРЫЕ УМЕРЛИ В РАЗЛИЧНЫХ УГОЛКАХ ЗЕМЛИ ЕЖЕДНЕВНО ПОСЛЕ ЗАХОДА СОЛНЦА<sup class=\"fn\">518</sup>"],["n",[[518,"Например, имам в мечети после вечерней молитвы (магриб) встаёт и говорит: «А теперь совершим погребальную молитву (салят аль-джаназа) за всех мусульман, которые скончались в течение последних суток». И это повторяется ежедневно. Нет сомнений в том, что это является новшеством."]]]],[["p","<b>См. «аль-Ихтиярат», 53; «аль-Мадхаль», 4/214; «ас-Сунан», 67; «Ахкам аль-джанаиз», стр. 316; «Тальхис аль-Джанаиз», стр. 101.</b>"],["sep",""],["p","ВОПРОС № 2: МОЛИТВА ЗА ОТСУТСТВУЮЩЕГО (САЛЯТ АЛЬ-ГАИБ)<sup class=\"fn\">519</sup>, КОГДА ИЗВЕСТНО, ЧТО ЗА НЕГО УЖЕ СОВЕРШИЛИ МОЛИТВУ ТАМ, ГДЕ ОН УМЕР"],["n",[[519,"<b>«Салят аль-гаиб»</b> - это молитва, которая совершается за того, кто умер вдали, где нет мусульман, которые могли бы совершить за него молитву «джаназа» при его захоронении. Абу Хурейра (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сообщил людям о кончине эфиопского негуса (наджаши) в тот же день, когда тот умер. Пророк (да благословит его Аллах и приветствует) вышел к месту молитвы, выстроил людей рядами и четырежды произнес слова «Аллаху акбар». Аль-Бухари, 1245; Муслим, 951."]]],["p","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «Ахкам аль-джанаиз», стр. 118-120, и в «Тальхис аль-Джанаиз», стр. 48: </b>"],["p","«Приведу тебе вкратце слова Ибн уль-Каййима (да помилует его Аллах) на эту тему. Он сказал в книге «Зад аль-ма′ад», 1/205-206<sup class=\"fn\">520</sup>:"],["n",[[520,"Слова имама Ибн уль-Каййима (да помилует его Аллах) здесь приведены с сокращениями."]]],["p","<i>«Не было обычаем и сунной пророка (да благословит его Аллах и приветствует) совершение молитвы за каждого умершего, который умер где-то в другом месте. Многие мусульмане умирали вдали от Медины, но он не совершал за них погребальную молитву. От него достоверно передано, что он совершил погребальную молитву за эфиопского негуса (наджаши). И в этом вопросе среди ученых три мнения:</i>"],["li","1.","<i>Этим самым он узаконил для своей общины совершение погребальной молитвы за каждого умершего где-то вдали. Это мнение аш-Шафи′и и Ахмада. </i>"],["li","2.","<i>А Абу Ханифа и Малик считали, что это – исключительная особенность пророка (да благословит его Аллах и приветствует), которая не касается других людей.</i>"],["li","3.","<i>Сказал шейх ислама Ибн Теймия:</i>"],["p","<i>«Правильное мнение заключается в следующем: если человек умер в местности, где за него не совершили погребальную молитву, то за него совершают «салят аль-гаиб», подобно тому, как пророк (да благословит его Аллах и приветствует) совершил такую молитву за эфиопского негуса (наджаши), ведь он умер среди неверующих, и там за него не совершали погребальную молитву. Если же за человека совершили молитву там, где он умер, то за него уже не совершают «салят аль-гаиб», ибо эта обязанность спала после того, как мусульмане совершили её. Пророк (да благословит его Аллах и приветствует) иногда совершал «салят аль-гаиб», а иногда не совершал. И его действие, и его отказ от действия считаются Сунной, и всему есть своё место. А Аллах знает лучше!». </i>"]],[["p","<i>Все эти три мнения есть в мазхабе Ахмада, но наиболее правильным является это разъяснение». </i>"],["p","Я (аль-Альбани) скажу: это мнение также выбрали некоторые ученые из числа шафиитов."],["p","Сказал аль-Хаттаби в «Ма′алим ас-Сунан»:"],["p","<i>«Эфиопский негус (наджаши) был мусульманином. Он уверовал в посланника Аллаха (да благословит его Аллах и приветствует) и подтвердил правдивость его пророчества, но при этом он скрывал свою веру. Когда мусульманин умирает, мусульмане обязаны совершить над ним молитву. Но эфиопский негус жил среди неверующих, и там не было никого, кто мог бы совершить над ним молитву, и поэтому посланник Аллаха (да благословит его Аллах и приветствует) был обязан сделать это сам, ведь он был пророком и покровителем этого умершего, и он ближе всего к нему из людей. И это – а Аллах знает лучше – причина, которая побудила пророка (да благословит его Аллах и приветствует) совершить \"салят аль-гаиб\". </i>"],["p","<i>Значит, если мусульманин умирает в какой-либо местности, где за него совершают погребальную молитву, то в другой местности уже не совершают за него \"салят аль-гаиб\". Если же люди знают, что за этого человека не совершили молитву по какой-то причине, то в соответствии с Сунной нужно совершить за него молитву, даже если он умер где-то далеко. </i>"],["p","<i>Совершая за него молитву, люди обращаются в сторону Каабы, а не в ту сторону, где умер этот человек. </i>"],["p","<i>Некоторые ученые считали нежелательным совершать \"салят аль-гаиб\". Они говорили, что это было исключительной особенностью пророка (да благословит его Аллах и приветствует), так как он как будто бы присутствовал возле эфиопского негуса. Ведь в некоторых хадисах пришло, что земля была выровнена перед ним так, что он увидел место, где умер негус</i><sup class=\"fn\">521</sup><i>. Это разъяснение является неправильным, ведь если посланник Аллаха (да благословит его Аллах и приветствует) совершал что-то из дел шариата, то мы должны следовать за ним в этом. Что касается дел, которые являются его исключительной особенностью, то об этом мы можем узнать только из религиозных доводов. И на ложность этого мнения указывает то, что он вышел к людям и выстроил их в ряды, и они совершали эту молитву вместе с ним. Отсюда мы понимаем, что это разъяснение является неправильным. А Аллах знает лучше!». </i>"],["n",[[521,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Упомянул ан-Науауи в «аль-Маджму′», 5/253, что этот хадис является выдумкой».  </i>"]]],["p","Также это мнение посчитал правильным ар-Руйяни (шафиитский ученый). Также это мнение выбрал Абу Дауд. Он привёл этот хадис в «Сунане», сказав: «Глава о молитве за мусульманина, который умер в земле многобожия». А среди поздних ученых это мнение выбрал выдающийся ученый, шейх Салих аль-Макбали, как это пришло в «Нейль аль-аутар», 4/43. В качестве довода он привёл добавку, которая пришла в некоторых версиях хадиса. В ней сказано:"]],[["p","<b><i>«Поистине, ваш брат умер не на вашей земле, так вставайте же и совершите за него молитву!». </i></b>"],["p","Цепочка передатчиков этой версии соответствует условиям аль-Бухари и Муслима."],["p","Также на отсутствие узаконенности совершения молитвы за каждого отсутствующего указывает следующее: когда скончались праведные халифы и другие сподвижники, никто из мусульман не совершил за них «салят аль-гаиб». Если бы они сделали это, то многие передатчики передали бы это."],["p","И сравни это с положением многих мусульман сегодня, когда они совершают молитву за каждого, кто умер вдали, особенно, если речь идёт об известном человеке. Иногда речь может идти просто о каком-то известном политическом деятеле, который не был известен своей праведностью или службой исламу. И это бывает даже тогда, когда человек умер в Мекке в сезон хаджа и тысячи людей уже совершили за него погребальную молитву. И если ты подумаешь над тем, что мы упомянули, ты однозначно поймешь, что это – новшество, в котором не будет сомневаться тот, кто знает сунну пророка (да благословит его Аллах и приветствует) и путь предшественников (да будет доволен ими Аллах)»."],["sep",""],["p","ВОПРОС № 3: НЕКОТОРЫЕ ЛЮДИ, СОВЕРШАЯ ПОГРЕБАЛЬНУЮ МОЛИТВУ, ГОВОРЯТ: «ПРЕЧИСТ ТОТ, КТО ОДОЛЕЛ РАБОВ СВОИХ ПОСРЕДСТВОМ СМЕРТИ. ПРЕЧИСТ ЖИВОЙ, КОТОРЫЙ НЕ УМИРАЕТ»."],["p","<b>См. «ас-Сунан уаль мубтада′ат», 66; «Ахкам аль-джанаиз», стр. 316; «Тальхис аль-Джанаиз», стр. 101.</b>"],["sep",""],["h2","ВОПРОС № 4: НЕКОТОРЫЕ ЛЮДИ, СОВЕРШАЯ ПОГРЕБАЛЬНУЮ МОЛИТВУ, СНИМАЮТ ОБУВЬ, ДАЖЕ ЕСЛИ НА НЕЙ НЕТ НЕЧИСТОТ"],["p","<b>См. «Ахкам аль-джанаиз», стр. 316; «Тальхис аль-Джанаиз», стр. 101.</b>"],["sep",""],["h2","ВОПРОС № 5: ИМАМ СТАНОВИТСЯ ВОЗЛЕ СЕРЕДИНЫ ТЕЛА МУЖЧИНЫ И ВОЗЛЕ ГРУДИ ЖЕНЩИНЫ<sup class=\"fn\">522</sup>"],["n",[[522,"Имам должен стоять напротив головы мужчины и напротив середины тела женщины."]]],["p","<b>См. «Ахкам аль-джанаиз», стр. 316; «Тальхис аль-Джанаиз», стр. 101.</b>"],["sep",""],["h2","ВОПРОС № 6: ЧТЕНИЕ ВСТУПИТЕЛЬНОЙ МОЛЬБЫ (ДУ′А АЛЬ-ИСТИФТАХ) В ПОГРЕБАЛЬНОЙ МОЛИТВЕ"],["p","<b>См. «Ахкам аль-джанаиз», стр. 316; «Тальхис аль-Джанаиз», стр. 101.</b>"],["sep",""],["h2","ВОПРОС № 7: ОТКАЗ ОТ ЧТЕНИЯ «АЛЬ-ФАТИХИ» И ЕЩЕ ДРУГОЙ СУРЫ В ПОГРЕБАЛЬНОЙ МОЛИТВЕ"],["p","<b>См. «Ахкам аль-джанаиз», стр. 316; «Тальхис аль-Джанаиз», стр. 101.</b>"],["sep",""],["h2","ВОПРОС № 8: ОТКАЗ ОТ ПРОИЗНЕСЕНИЯ САЛЯМА В ПОГРЕБАЛЬНОЙ МОЛИТВЕ<sup class=\"fn\">523</sup>"],["n",[[523,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Этим новшеством выделились (шииты) имамиты среди всех мусульман, как это пришло в книге «Мифтах аль-карама», 1/483. Это – одна из их книг». </i>"]]],["p","<b>См. «Ахкам аль-джанаиз», стр. 316; «Тальхис аль-Джанаиз», стр. 101.</b>"],["sep",""],["p","ВОПРОС № 9: НЕКОТОРЫЕ ЛЮДИ ПОСЛЕ ПОГРЕБАЛЬНОЙ МОЛИТВЫ ГОВОРЯТ ГРОМКИМ ГОЛОСОМ: «ЧТО ВЫ СКАЖЕТЕ О НЁМ?!», А ПРИСУТСТВУЮЩИЕ ОТВЕЧАЮТ: «ОН БЫЛ ОДНИМ ИЗ ПРАВЕДНИКОВ» И Т. П."],["h3","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «Ахкам аль-джанаиз», стр. 62:</b>"]],[["p","«Некоторые люди говорят после погребальной молитвы: «Что вы скажете о нём?! Отзовитесь о нём хорошо!», а другие отвечают: «Праведник!», или: «Был благим человеком!» и т. п. Об этом не говорится в хадисе ни в коем случае<sup class=\"fn\">524</sup>. Напротив, это является скверным новшеством, ибо предшественники так не поступали. К тому же, как правило, люди, которые говорят так, даже не знают умершего. А бывает даже так, что они говорят о нём обратное тому, что знают, ибо так их попросил сказать тот человек. Они думают, что это поможет умершему. Они даже не понимают, что полезное свидетельство – это свидетельство, которое соответствует действительности»<sup class=\"fn\">525</sup>."],["n",[[524,"Речь идёт о хадисе, в котором сказано: <b><i>«Если вы похвалите кого-либо (из умерших), для него станет обязательным Рай, а если вы отзоветесь о ком-то (из умерших) плохо, для него станет обязательным Ад». </i></b>"],[525,"То есть, если человек был грешником, ему не поможет то, что после молитвы люди специально назовут его праведным, желая этим помочь ему."]]],["sep",""],["h3","<b>Также наш шейх, да помилует его Всевышний Аллах, сказал в «ас-Сахиха», 3/296:</b>"],["p","«Некоторые люди говорят после погребальной молитвы: «Что вы скажете о нём?! Отзовитесь о нём хорошо!». Это является скверным новшеством!»."],["sep",""],["h2","ГЛАВА № 6 – НОВШЕСТВА, СВЯЗАННЫЕ С ЗАХОРОНЕНИЕМ"],["p","ВОПРОС № 1: НЕКОТОРЫЕ ЛЮДИ РЕЖУТ БУЙВОЛА, КОГДА ТЕЛО ПОКОЙНОГО ПРИНОСЯТ НА КЛАДБИЩЕ. ЭТО ДЕЛАЕТСЯ ДО ЕГО ЗАХОРОНЕНИЯ. ЗАТЕМ ЭТО МЯСО РАЗДАЮТ ТЕМ, КТО ПРИСУТСТВУЕТ НА ПОХОРОНАХ"],["p","<b>См. «аль-Ибда′», 114; «Ахкам аль-джанаиз», стр. 317; «Тальхис аль-Джанаиз», стр. 101.</b>"],["sep",""],["p","ВОПРОС № 2: НЕКОТОРЫЕ ЛЮДИ РЕЖУТ ЖИВОТНОЕ, КОГДА ПОГРЕБАЛЬНЫЕ НОСИЛКИ ВЫНОСЯТ ИЗ ДОМА, А ЗАТЕМ КЛАДУТ ЕГО КРОВЬ В МОГИЛУ УМЕРШЕГО"],["p","<b>См. «Ахкам аль-джанаиз», стр. 317; «Тальхис аль-Джанаиз», стр. 101.</b>"],["sep",""],["h2","ВОПРОС № 3: ПОМИНАНИЕ АЛЛАХА (ЗИКР) ВОЗЛЕ ПОГРЕБАЛЬНЫХ НОСИЛОК ПЕРЕД ЗАХОРОНЕНИЕМ"],["p","<b>См. «ас-Сунан», 67; «Ахкам аль-джанаиз», стр. 317; «Тальхис аль-Джанаиз», стр. 101.</b>"],["sep",""],["h2","ВОПРОС № 4: ПРОИЗНЕСЕНИЕ АЗАНА ВО ВРЕМЯ ОПУСКАНИЯ ТЕЛА В МОГИЛУ"],["p","<b>См. «Хашият Ибн ′Абидин», 1/837; «Ахкам аль-джанаиз», стр. 317; «Тальхис аль-Джанаиз», стр. 101.</b>"],["sep",""],["p","ВОПРОС № 5: НЕКОТОРЫЕ ЛЮДИ КЛАДУТ ПОЧВУ С «МОГИЛЫ ХУСЕЙНА» (МИР ЕМУ) ВМЕСТЕ С УМЕРШИМ, КОГДА ОПУСКАЮТ ЕГО В МОГИЛУ, СЧИТАЯ, ЧТО ОНА ЗАЩИЩАЕТ ОТ ЛЮБОГО СТРАХА<sup class=\"fn\">526</sup>"],["n",[[526,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Об этом говорится в (шиитской) книге \"Мифтах аль-карама\", 1/497». </i>"]]],["p","<b>См. «Ахкам аль-джанаиз», стр. 317; «Тальхис аль-Джанаиз», стр. 101.</b>"],["sep",""],["h2","ВОПРОС № 6: НЕКОТОРЫЕ ЛЮДИ РАССЫПАЮТ ПЕСОК НА ДНЕ МОГИЛЫ БЕЗ ВСЯКОЙ НУЖДЫ В ЭТОМ"],["p","<b>См. «аль-Мадхаль», 3/261; «Ахкам аль-джанаиз», стр. 317; «Тальхис аль-Джанаиз», стр. 101.</b>"],["sep",""],["h2","ВОПРОС № 7: НЕКОТОРЫЕ ЛЮДИ КЛАДУТ ПОДУШКУ ИЛИ НЕЧТО ПОДОБНОЕ ПОД ГОЛОВУ ПОКОЙНОГО В МОГИЛЕ"]],[["p","<b>См. «аль-Мадхаль», 3/260; «Ахкам аль-джанаиз», стр. 317; «Тальхис аль-Джанаиз», стр. 102.</b>"],["sep",""],["h2","ВОПРОС № 8: НЕКОТОРЫЕ ЛЮДИ ОБРЫЗГИВАЮТ РОЗОВОЙ ВОДОЙ ТЕЛО УМЕРШЕГО В МОГИЛЕ"],["p","<b>См. «аль-Мадхаль», 3/262, 2/222; «Ахкам аль-джанаиз», стр. 317; «Тальхис аль-Джанаиз», стр. 102.</b>"],["sep",""],["p","ВОПРОС № 9: ПРИСУТСТВУЮЩИЕ НА ПОХОРОНАХ СЫПЛЮТ ЗЕМЛЮ ТЫЛЬНОЙ СТОРОНОЙ ЛАДОНИ И ГОВОРЯТ: «ИННА ЛИ ЛЛЯХИ УА ИННА ИЛЯЙХИ РАДЖИ′УН» (ВОИСТИНУ, МЫ ПРИНАДЛЕЖИМ АЛЛАХУ, И К НЕМУ МЫ ВЕРНЕМСЯ)<sup class=\"fn\">527</sup>"],["n",[[527,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Это – обычай (шиитов) имамитов, как это пришло в книге \"Мифтах аль-карама\", 1/499. Кажется, будто бы они хотят этим действием противоречить суннитам, которые сыплют землю так же, как пророк (да благословит его Аллах и приветствует) – внутренней стороной ладоней». </i>"]]],["p","<b>См. «Ахкам аль-джанаиз», стр. 317; «Тальхис аль-Джанаиз», стр. 102.</b>"],["sep",""],["p","ВОПРОС № 10: НЕКОТОРЫЕ ЛЮДИ БРОСАЮТ ПЕРВУЮ ГОРСТЬ ЗЕМЛИ И ЧИТАЮТ: «МЫ СОТВОРИЛИ ВАС ИЗ НЕЕ [ИЗ ЗЕМЛИ]», ЗАТЕМ БРОСАЮТ ВТОРУЮ ГОРСТЬ И ЧИТАЮТ: «В НЕЕ МЫ ВАС ВЕРНЕМ», А ЗАТЕМ БРОСАЮТ ТРЕТЬЮ ГОРСТЬ И ЧИТАЮТ: «И ИЗ НЕЕ ВЫВЕДЕМ ЕЩЕ РАЗ»<sup class=\"fn\">528</sup>"],["n",[[528,"Сура «Та Ха», аят 55."]]],["p","<b>См. «Ахкам аль-джанаиз», стр. 193-194, 318; «Тальхис аль-Джанаиз», стр. 102.</b>"],["h3","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «Ахкам аль-джанаиз», стр. 193-194:</b>"],["p","«Некоторые поздние знатоки фикха посчитали желательным говорить, когда человек бросает первую горсть земли<sup class=\"fn\">529</sup>: <b>«Мы сотворили вас из нее». </b>А затем говорить: <b>«В нее Мы вас вернем», </b>когда он бросает вторую горсть земли. И затем говорить: <b>«И из нее выведем еще раз»</b>, когда он бросает третью горсть земли."],["n",[[529,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Согласно Сунне, если человек находится возле могилы, ему желательно бросить три горсти земли своими руками, когда тело умершего опустили в нишу (ляхд) и закрыли её. Но во время этого не произносится какое-либо поминание ни из Корана, ни из достоверной Сунны». </i>"]]],["p","Сказал ан-Науауи, 5/293-294:"],["p","<i>«В хадисе Абу Умамы (да будет доволен им Аллах) сказано: «Когда Умм Кульсум, дочь посланника Аллаха (да благословит его Аллах и приветствует), опустили в могилу, посланник Аллаха (да благословит его Аллах и приветствует) прочитал: </i><b>\"Мы сотворили вас из нее, в нее Мы вас вернем и из нее выведем еще раз\"</b><i>». Передал имам Ахмад со слов ′Убейдуллаха ибн Захра, который передал от ′Али ибн Зейда ибн Джуд′ана, а тот – от аль-Касима. Все они трое являются слабыми. Однако в таких случаях мы можем опираться на хадисы, в которых говорится о достоинствах деяний, даже если у них слабая цепочка передатчиков. Разрешено поступать в соответствии с ними, когда речь идёт о побуждении к благому или предостережении от дурного. И этот хадис как раз относится к такой категории. А Аллах знает лучше!». </i>"]],[["p","Мы ответим на это в нескольких пунктах:"],["p","<b>Во-первых</b>, в хадисе вообще не говорится о желательности такой последовательности<sup class=\"fn\">530</sup>. То есть в своей основе в нём нет довода, даже если бы он был достоверным."],["n",[[530,"То есть в хадисе сказано, что посланник Аллаха (да благословит его Аллах и приветствует) прочитал этот аят, но нет таких подробностей, что во время первой горсти он прочитал первую часть аята, во время второй – вторую, во время третьей – последнюю часть аята."]]],["p","<b>Во-вторых</b>, нигде в шариате не установлена такая последовательность, чтобы мы могли сказать, что этот хадис можно использовать, так как речь идёт о благом деянии. Напротив, если мы называем это дело дозволенным, то мы устанавливаем узаконенность этого дела через слабый хадис, то есть как минимум мы считаем это желательно. Желательность – это одно из пяти религиозных постановлений, которые могут быть установлены только через достоверный хадис. В таких вопросах слабые хадисы не приносят никакой пользы по единогласному мнению ученых."],["p","<b>В-третьих</b>, этот хадис является очень слабым. Более того он является выдуманным, как об этом сказал Ибн Хиббан»."],["sep",""],["p","ВОПРОС № 11: НЕКОТОРЫЕ ЛЮДИ БРОСАЮТ ПЕРВУЮ ГОРСТЬ ЗЕМЛИ И ЧИТАЮТ: «С ИМЕНЕМ АЛЛАХА!»; БРОСАЮТ ВТОРУЮ ГОРСТЬ И ЧИТАЮТ: «ВЛАСТЬ ПРИНАДЛЕЖИТ АЛЛАХУ!»; БРОСАЮТ ТРЕТЬЮ ГОРСТЬ И ЧИТАЮТ: «МОГУЩЕСТВО ПРИНАДЛЕЖИТ АЛЛАХУ!»; БРОСАЮТ ЧЕТВЕРТУЮ ГОРСТЬ И ЧИТАЮТ: «ВЕЛИЧИЕ ПРИСУЩЕ АЛЛАХУ!»; БРОСАЮТ ПЯТУЮ ГОРСТЬ И ЧИТАЮТ: «ПРОЩЕНИЕ ПРИНАДЛЕЖИТ АЛЛАХУ!»; БРОСАЮТ ШЕСТУЮ ГОРСТЬ И ЧИТАЮТ: «МИЛОСТЬ ПРИНАДЛЕЖИТ АЛЛАХУ!»; ЗАТЕМ БРОСАЮТ СЕДЬМУЮ ГОРСТЬ И ЧИТАЮТ СЛОВА ВСЕВЫШНЕГО: «ВСЕ НА НЕЙ [НА ЗЕМЛЕ] СМЕРТНЫ»<sup class=\"fn\">531</sup>, И ЗАТЕМ ЧИТАЮТ СЛОВА ВСЕВЫШНЕГО: «МЫ СОТВОРИЛИ ВАС ИЗ НЕЕ [ИЗ ЗЕМЛИ]» И ДО КОНЦА АЯТА."],["n",[[531,"Сура «ар-Рахман», аят 26."]]],["p","<b>См. «Ахкам аль-джанаиз», стр. 318; «Тальхис аль-Джанаиз», стр. 102.</b>"],["sep",""],["p","ВОПРОС № 12: НЕКОТОРЫЕ ЛЮДИ ВО ВРЕМЯ ЗАХОРОНЕНИЯ УМЕРШЕГО ЧИТАЮТ СЕМЬ СУР: «АЛЬ-ФАТИХА» (№ 1), «АЛЬ-ФАЛЯК» (№ 113), «АН-НАС» (№ 114), «АЛЬ-ИХЛЯС» (№ 112), «АН-НАСР» (№ 110), «АЛЬ-КАФИРУН» (№ 109) И «АЗ-ЗАЛЬЗАЛЯ» (№ 99), А ЗАТЕМ ЭТУ МОЛЬБУ: «О АЛЛАХ! ПОИСТИНЕ, Я ПРОШУ ТЕБЯ ЧЕРЕЗ ТВОЁ ВЕЛИКОЕ ИМЯ! Я ПРОШУ ТЕБЯ ЧЕРЕЗ ТВОЁ ИМЯ, КОТОРОЕ ЯВЛЯЕТСЯ ОПОРОЙ РЕЛИГИИ! Я ПРОШУ ТЕБЯ… Я ПРОШУ ТЕБЯ…», И ТАК ДАЛЕЕ<sup class=\"fn\">532</sup>."],["n",[[532,"То есть они выдумали мольбу, которой нет в религиозных текстах, а затем сказали, что желательно читать её в этом месте без какого-либо на то довода."]]],["p","<b>См. «Ахкам аль-джанаиз», стр. 318; «Тальхис аль-Джанаиз», стр. 102.</b>"],["sep",""],["h2","ВОПРОС № 13: НЕКОТОРЫЕ ЛЮДИ ЧИТАЮТ СУРУ «АЛЬ-ФАТИХА» ВОЗЛЕ ГОЛОВЫ УМЕРШЕГО И НАЧАЛО СУРЫ «АЛЬ-БАКАРА» (№ 2) У ЕГО НОГ."]],[["p","<b>См. «Ахкам аль-джанаиз», стр. 318; «Тальхис аль-Джанаиз», стр. 102.</b>"],["sep",""],["h2","ВОПРОС № 14: НЕКОТОРЫЕ ЛЮДИ ЧИТАЮТ КОРАН, КОГДА ЗАСЫПАЮТ ЗЕМЛЕЙ МОГИЛУ"],["p","<b>См. «аль-Мадхаль», 3/262-263; «Ахкам аль-джанаиз», стр. 318; «Тальхис аль-Джанаиз», стр. 102.</b>"],["sep",""],["h2","ВОПРОС № 15: ЧТЕНИЕ ТАЛЬКЫНА УМЕРШЕМУ<sup class=\"fn\">533</sup>"],["n",[[533,"Талькын заключается в том, что некий человек становится возле могилы и начинает «подсказывать» умершему ответы на вопросы ангелов. Он говорит: «Если ангелы зададут тебе такой-то вопрос, то скажи то-то и то-то. А если они зададут тебе такой вопрос, то скажи им то-то и то-то», и так далее."]]],["h3","<b>Сказал аль-Алюси в «аль-Аят аль-беййинат», стр. 57:</b>"],["p","«Что касается талькына после смерти, когда умерший в могиле, то некоторые сказали, что его нужно читать из-за переданного хадиса, и они отнесли это мнение к приверженцам сунны и единой общины, а противоречие в этом вопросе – к му′тазилитам. А некоторые сказали, что это и не приказывается, и не запрещается»."],["p","<b>Сказал наш шейх, да помилует его Аллах, опровергая эти слова в своих примечаниях к книге «аль-Аят аль-беййинат», стр. 57-58:</b>"],["p","«Эти слова отвергаются, так как талькын – это напоминание, а не какое-то мирское дело или обычай, чтобы можно было сказать то, что он сказал. Это именно вопрос поклонения, и либо он является узаконенным в шариате, и тогда нужно его приказывать (даже если это будет в форме желательности), либо он является неузаконенным, и тогда его запрещают, ибо в таком случае он будет относиться к новшествам, а новшества запрещены. Обрати же на это внимание!»."],["h3","<b>Затем сказал аль-Алюси, да помилует его Всевышний Аллах, на стр. 62-63:</b>"],["p","«Знай, что относительно чтения талькына перед смертью мы не знаем никаких разногласий. Что же касается чтения талькына после смерти, что мы приводили из книги «аль-Хидая» и других книг, то имамы и учёные разногласили относительно этого. Среди ханафитов в этом вопросе три мнения:"],["li","1.","Разрешено читать «талькын» после смерти, так как умершему возвращают дух, чтобы он ответил на вопросы."],["li","2.","Талькын не читается."],["li","3.","Талькын не приказывается и не запрещается."],["p","Шафииты считают, что нужно читать «талькын». Сказал Ибн Хаджар (аль-Хейтами) в «ат-Тухфа»: <i>«Желательно читать талькын разумному, который достиг зрелости, или же сумасшедшему, если он до этого был разумным, и даже мученику. Это делается после окончания захоронения, так как об этом пришло сообщение. Да, оно является слабым, но его поддерживают другие хадисы, и к тому же речь идёт о благом деянии. Именно поэтому слова Ибн ′Абд ус-Саляма о том, что это – новшество, являются неправильными». </i>"],["p","<b>Сказал наш шейх, да помилует его Всевышний Аллах, опровергая слова: «Да, оно является слабым, но его поддерживают другие хадисы»:</b>"]],[["p","«Никак нет! Те подкрепляющие хадисы, на которые он указывает, не годятся для поддержки, ибо либо они не являются словами пророка (да благословит его Аллах и приветствует), либо переданы через прерванную цепочку. Именно поэтому Ибн уль-Каййим сказал о том, что этот хадис не является достоверным. А ан-Науауи и другие назвали его слабым. Я разобрал этот вопрос в книге «Сильсилят аль-ахадис ад-да′ифа», 599»."],["p","<b>Затем он, да помилует его Всевышний Аллах, сказал, поддерживая слова аль-′Изза ибн ′Абд ус-Саляма, да помилует его Всевышний Аллах, о том, что талькын – это новшество:</b>"],["p","«Его слова являются верными, ибо здесь не только хадис о талькыне является слабым, но и сам талькын противоречит пути пророка (да благословит его Аллах и приветствует). Достоверно передано, что он хоронил человека, становился возле его могилы и просил для него у Аллаха стойкости и прощения грехов, и велел делать это присутствующим, а всё, что противоречит этому, является новшеством без каких-либо сомнений. Об этом также сказал имам ас-Сан′ани. Я разобрал этот вопрос немного подробнее в книге «Ахкам аль-джанаиз», стр. 155-156»."],["sep",""],["h3","<b>Также сказал наш шейх, да помилует его Аллах, в «Ахкам аль-джанаиз», стр. 197-198: </b>"],["p","«<b>В-четвертых</b>, над умершим не произносится тот талькын, который известен сегодня, ибо хадис, пришедший относительно него, не является достоверным. Пророк (да благословит его Аллах и приветствует) становился над могилой и просил для умершего стойкости и прощения, и велел делать то же самое всем присутствующим."],["p","′Усман ибн ′Аффан (да будет доволен им Аллах) рассказывал: <i>«Когда завершали хоронить умершего, пророк (да благословит его Аллах и приветствует) становился над его (могилой) и говорил: </i><b><i>\"Просите прощения для вашего брата и просите для него стойкости, ибо его сейчас спрашивают!\"</i></b><i>». </i>Передали Абу Дауд, 2/70; аль-Хаким, 1/370; аль-Бейхакы, 4/56; ′Абдуллах ибн Ахмад в «Зауаид аз-Зухд», стр. 129. Аль-Хаким сказал: <i>«Цепочка передатчиков достоверная», </i>и с ним согласился аз-Захаби, и дело обстоит именно так, как они сказали. И сказал ан-Науауи, 5/292: <i>«Цепочка передатчиков хорошая». </i>"],["sep",""],["h3","<b>Также сказал наш шейх, да помилует его Всевышний Аллах, в «ас-Сахиха», 1/838: </b>"],["p","«Талькын после смерти, во-первых, является новшеством. Такого не пришло в Сунне. А, во-вторых, в нём нет никакой пользы, ибо умерший переместился из обители деяний в обитель воздаяния, и он уже не может принять напоминание. Аллах сказал: <b>«…чтобы он предостерегал тех, кто жив…»</b><sup class=\"fn\">534</sup>»."],["n",[[534,"Сура «Йа Син», аят 70."]]],["sep",""],["h3","<b>Также он, да помилует его Всевышний Аллах, сказал в «ад-Да′ифа», 2/65:</b>"]],[["p","«Сказал ас-Сан′ани в «Субуль ас-салям», 2/161: <i>«Из слов имамов, глубоко разбирающихся в религии, следует, что этот хадис (хадис о талькыне) является слабым. Совершение же этого является новшеством и не следует обольщаться тем, что многие люди его совершают». </i>"],["p","И не нужно здесь приводить известные слова о том, что можно поступать в соответствии со слабым хадисом, если речь идёт о достоинствах благих дел. Это правило касается тех дел, узаконенность которых установлена Кораном или достоверной Сунной. Если же нет ни того, ни другого, то запрещено поступать в соответствии со слабым хадисом, ибо речь идёт об установлении законов, а это нельзя делать на основе слабого хадиса, ибо он несёт в себе лишь слабое предположение по единогласному мнению. Разве можно совершать дела согласно этому?! Пусть на это обратит внимание тот, кто желает безопасности для своей религии, ибо многие люди беспечны к этому. Мы просим у Всевышнего Аллаха наставления и содействия!»."],["sep",""],["h2","ВОПРОС № 16: УСТАНОВЛЕНИЕ ДВУХ КАМНЕЙ У МОГИЛЫ ЖЕНЩИНЫ"],["p","<b>См. «Ахкам аль-джанаиз», стр. 318; «Тальхыс аль-Джанаиз», стр. 102.</b>"],["sep",""],["h2","ВОПРОС № 17: ПРИЧИТАНИЯ ПО ПОКОЙНОМУ ВОЗЛЕ МОГИЛЫ ПОСЛЕ ЕГО ЗАХОРОНЕНИЯ"],["p","<b>См. «Ахкам аль-джанаиз», стр. 318; «Тальхыс аль-Джанаиз», стр. 102;</b>"],["sep",""],["h2","ВОПРОС № 18: НЕКОТОРЫЕ ЛЮДИ ПЕРЕНОСЯТ ТЕЛО УМЕРШЕГО ПЕРЕД ЗАХОРОНЕНИЕМ К «СВЯТЫМ МЕСТАМ»<sup class=\"fn\">535</sup>"],["n",[[535,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Так поступают имамиты (шииты), как это пришло в книге \"Мифтах аль-карама\", 1/507». </i>"]]],["p","<b>См. «Ахкам аль-джанаиз», стр. 319; «Тальхыс аль-Джанаиз», стр. 102.</b>"],["sep",""],["h2","ВОПРОС № 19: НЕКОТОРЫЕ ЛЮДИ ОСТАЮТСЯ ЖИТЬ ВОЗЛЕ МОГИЛЫ ИЛИ НЕДАЛЕКО ОТ НЕЁ ПОСЛЕ ЗАХОРОНЕНИЯ УМЕРШЕГО"],["p","<b>См. «Ахкам аль-джанаиз», стр. 319; «Тальхыс аль-Джанаиз», стр. 102.</b>"],["sep",""],["p","ВОПРОС № 20: НЕКОТОРЫЕ ЛЮДИ ПОСЛЕ ВОЗВРАЩЕНИЯ С ПОХОРОН ОТКАЗЫВАЮТСЯ ВХОДИТЬ В ДОМ, ПОКА НЕ ПОСТИРАЮТ СВОЮ ОДЕЖДУ ОТ «СЛЕДОВ» УМЕРШЕГО"],["p","<b>См. «аль-Мадхаль», 3/276; «Ахкам аль-джанаиз», стр. 319; «Тальхыс аль-Джанаиз», стр. 102.</b>"],["sep",""],["h2","ВОПРОС № 21: НЕКОТОРЫЕ ЛЮДИ КЛАДУТ ЕДУ И ПИТЬЁ ВОЗЛЕ МОГИЛ ДЛЯ ТОГО, ЧТОБЫ ИХ ВЗЯЛИ ДРУГИЕ ЛЮДИ"],["p","<b>См. «Ахкам аль-джанаиз», стр. 319; «Тальхыс аль-Джанаиз», стр. 102.</b>"],["sep",""],["h2","ВОПРОС № 22: РАЗДАЧА МИЛОСТЫНИ ВОЗЛЕ МОГИЛЫ"],["p","<b>См. «аль-Иктида», 183; «Ахкам аль-джанаиз», стр. 319; «Тальхыс аль-Джанаиз», стр. 103.</b>"],["sep",""],["p","ВОПРОС № 23: НЕКОТОРЫЕ ЛЮДИ ПОЛИВАЮТ МОГИЛУ (В ТОЙ ЧАСТИ, ГДЕ ГОЛОВА УМЕРШЕГО) ВОДОЙ, А ЗАТЕМ ОБХОДЯТ ЕЁ И ВЫЛИВАЮТ ОСТАТКИ ВОДЫ НА ЕЁ СЕРЕДИНУ<sup class=\"fn\">536</sup>"],["n",[[536,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Так поступают имамиты (шииты), как это пришло в книге \"Мифтах аль-карама\", 1/500».</i>"]]],["p","<b>См. «Ахкам аль-джанаиз», стр. 319; «Тальхыс аль-Джанаиз», стр. 103.</b>"],["sep",""],["h2","ГЛАВА № 7 – НОВШЕСТВА, СВЯЗАННЫЕ С СОБОЛЕЗНОВАНИЯМИ И НЕКОТОРЫЕ ДРУГИЕ ВОПРОСЫ"],["h2","ВОПРОС № 1: ПРОВЕДЕНИЕ СОБОЛЕЗНОВАНИЙ ВОЗЛЕ МОГИЛ"]],[["p","<b>См. «Хашия Ибн ′Абидин», 1/843; «Ахкам аль-джанаиз», стр. 320; «Тальхыс аль-Джанаиз», стр. 103.</b>"],["sep",""],["h2","ВОПРОС № 2: СОБРАНИЕ В ОПРЕДЕЛЕННОМ МЕСТЕ ДЛЯ ВЫРАЖЕНИЯ СОБОЛЕЗНОВАНИЙ"],["p","<b>См. «Зад аль-ма′ад», 1/304; «Сафар ас-са′ада», стр. 57, аль-Файруз Абади; «Ислях аль-масаджид ′ан аль-бида′ уаль ′ауаид», стр. 180-181, аль-Касими; «Ахкам аль-джанаиз», стр. 320; «Тальхыс аль-Джанаиз», стр. 103.</b>"],["sep",""],["h2","ВОПРОС № 3: ОГРАНИЧЕНИЕ СОБОЛЕЗНОВАНИЙ ТРЁМЯ ДНЯМИ"],["p","<b>См. «Ахкам аль-джанаиз», стр. 320; «Тальхыс аль-Джанаиз», стр. 103.</b>"],["sep",""],["p","ВОПРОС № 4: РАССТИЛАНИЕ КОВРОВ В ДОМЕ УМЕРШЕГО, ЧТОБЫ ПРИХОДЯЩИЕ НА СОБОЛЕЗНОВАНИЯ МОГЛИ САДИТЬСЯ. ЭТИ КОВРЫ ОСТАВЛЯЮТ НА ПРОТЯЖЕНИИ СЕМИ ДНЕЙ, А ЗАТЕМ УБИРАЮТ"],["p","<b>См. «аль-Мадхаль», 3/279-280; «Ахкам аль-джанаиз», стр. 320; «Тальхыс аль-Джанаиз», стр. 103.</b>"],["sep",""],["p","ВОПРОС № 5: НЕКОТОРЫЕ ЛЮДИ, ВЫРАЖАЯ СОБОЛЕЗНОВАНИЯ, ГОВОРЯТ: «ПУСТЬ АЛЛАХ УВЕЛИЧИТ ТВОЮ НАГРАДУ И ВНУШИТ ТЕБЕ ТЕРПЕНИЕ. ПУСТЬ АЛЛАХ НАДЕЛИТ НАС И ТЕБЯ БЛАГОДАРНОСТЬЮ. ПОИСТИНЕ, НАШИ ДУШИ, НАШИ БОГАТСТВА, НАШИ СЕМЬИ И НАШИ ДЕТИ – ЭТО ДАРЫ АЛЛАХА, КОТОРЫЕ ОН ПРЕДОСТАВИЛ НАМ НА ВРЕМЯ. АЛЛАХ ДАРОВАЛ ТЕБЕ ЭТОГО ЧЕЛОВЕКА КАК РАДОСТЬ, А ЗАТЕМ ЗАБРАЛ ЕГО, ПООБЕЩАВ ВЗАМЕН БОЛЬШУЮ НАГРАДУ: БЛАГОСЛОВЕНИЕ, МИЛОСТЬ И ПРЯМОЙ ПУТЬ, ЕСЛИ ТЫ БУДЕШЬ НАДЕЯТЬСЯ НА НАГРАДУ АЛЛАХА. ПРОЯВЛЯЙ ЖЕ ТЕРПЕНИЕ! И НЕ ДЕЛАЙ ТАК, ЧТОБЫ ТВОЁ НЕГОДОВАНИЕ УНИЧТОЖИЛО ТВОЮ НАГРАДУ, ИБО ПОТОМ ТЫ СТАНЕШЬ СОЖАЛЕТЬ. И ЗНАЙ, ЧТО НЕГОДОВАНИЕ НИКОГО НЕ ВЕРНЁТ. ОНО НЕ ЗАЩИТИТ ОТ ПЕЧАЛИ И БЕДЫ»."],["p","А ТАКЖЕ: «ПОИСТИНЕ, В АЛЛАХЕ УТЕШЕНИЕ ВСЯКОГО НЕСЧАСТЬЯ И ЗАМЕНА ВСЕМУ УШЕДШЕМУ. ДОВЕРЯЙТЕ ЖЕ АЛЛАХУ, ЛИШЬ НА НЕГО НАДЕЙТЕСЬ, ВЕДЬ, ПОИСТИНЕ, ЛИШЁННЫЙ ТОТ, КТО ЛИШИЛСЯ НАГРАДЫ»<sup class=\"fn\">537</sup>."],["n",[[537,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Первая мольба передаётся от пророка (да благословит его Аллах и приветствует). Передаётся, что он произнёс эти слова в качестве соболезнования Му′азу ибн Джабалю, когда умер его сын. Однако этот хадис является выдуманным. А вторая мольба пришла в истории о том, что Хидр выразил так соболезнования семье пророка (да благословит его Аллах и приветствует), когда тот умер. Этот хадис является слабым. Его передал аш-Шафи′и в «Муснаде», 1820. Ибн Касир назвал его слабым в «Тарихе», 1/332». </i>"]]],["p","<b>См. «Ахкам аль-джанаиз», стр. 320; «Тальхыс аль-Джанаиз», стр. 103.</b>"],["sep",""],["h2","ВОПРОС № 6: УСТРАИВАНИЕ УГОЩЕНИЙ ЧЛЕНАМИ СЕМЬИ УМЕРШЕГО"],["p","<b>См. «Тальбис Иблис», 341; «Фатх уль-Кадир», 1/473, Ибн уль-Хумам; «аль-Мадхаль», 3/275-276; «Ислях аль-масаджид», 181; «Ахкам аль-джанаиз», стр. 321; «Тальхыс аль-Джанаиз», стр. 103.</b>"],["sep",""],["h2","ВОПРОС № 7: УСТРАИВАНИЕ УГОЩЕНИЙ В ЧЕСТЬ УМЕРШЕГО В ПЕРВЫЙ ДЕНЬ, НА СЕДЬМОЙ ДЕНЬ, НА СОРОКОВОЙ ДЕНЬ И В ГОДОВЩИНУ СМЕРТИ"]],[["p","<b>См. «Ахкам аль-джанаиз», стр. 321; «Тальхыс аль-Джанаиз», стр. 103.</b>"],["sep",""],["h2","ВОПРОС № 8: УСТРАИВАНИЕ УГОЩЕНИЙ В ПЕРВЫЙ ЧЕТВЕРГ ПОСЛЕ СМЕРТИ ЧЕЛОВЕКА"],["p","<b>См. «Ахкам аль-джанаиз», стр. 321; «Тальхыс аль-Джанаиз», стр. 103.</b>"],["sep",""],["h2","ВОПРОС № 9: ОТВЕТ НА ПРИГЛАШЕНИЕ ЧЛЕНОВ СЕМЬИ УМЕРШЕГО К УГОЩЕНИЮ"],["p","<b>См. «Ахкам аль-джанаиз», стр. 321; «Тальхыс аль-Джанаиз», стр. 103.</b>"],["sep",""],["p","ВОПРОС № 10: НЕКОТОРЫЕ ЛЮДИ ГОВОРЯТ: «СТОЛ С УГОЩЕНИЯМИ В ТЕЧЕНИЕ ТРЁХ ДНЕЙ НЕ ДОЛЖЕН УБИРАТЬ НИКТО, КРОМЕ ТОГО, КТО ЕГО РАЗЛОЖИЛ»"],["p","<b>См. «аль-Мадхаль», 3/276; «Ахкам аль-джанаиз», стр. 321; «Тальхыс аль-Джанаиз», стр. 103.</b>"],["sep",""],["h2","ВОПРОС № 11: ПРИГОТОВЛЕНИЕ ИЛИ ПОКУПКА ЗАЛЯБИИ<sup class=\"fn\">538</sup> НА СЕДЬМОЙ ДЕНЬ ПОСЛЕ СМЕРТИ ЧЕЛОВЕКА"],["n",[[538,"Десерт, популярный в Индии, на Ближнем Востоке и в Северной Африке."]]],["p","<b>См. «аль-Мадхаль», 3/292; «Ахкам аль-джанаиз», стр. 321; «Тальхыс аль-Джанаиз», стр. 103.</b>"],["sep",""],["p","ВОПРОС № 12: ПРЕДСМЕРТНОЕ ЗАВЕЩАНИЕ УСТРОИТЬ УГОЩЕНИЕ В ДЕНЬ СМЕРТИ ЧЕЛОВЕКА ИЛИ ПОСЛЕ ЭТОГО И РАЗДАТЬ ОПРЕДЕЛЕННОЕ КОЛИЧЕСТВО ДЕНЕГ ТЕМ, КТО БУДЕТ ЧИТАТЬ КОРАН ЗА ЕГО ДУШУ ИЛИ ПРОИЗНОСИТЬ СЛОВА ПРОСЛАВЛЕНИЯ АЛЛАХА"],["p","<b>См. «ат-Тарика аль-Мухаммадия», 4/325; «Ахкам аль-джанаиз», стр. 321; «Тальхыс аль-Джанаиз», стр. 103.</b>"],["sep",""],["p","ВОПРОС № 13: ПРЕДСМЕРТНОЕ ЗАВЕЩАНИЕ  О ТОМ, ЧТОБЫ МУЖЧИНЫ НОЧЕВАЛИ ВОЗЛЕ ЕГО МОГИЛЫ НА ПРОТЯЖЕНИИ СОРОКА НОЧЕЙ (ИЛИ БОЛЬШЕ ЭТОГО, ИЛИ МЕНЬШЕ ЭТОГО)"],["p","<b>См. «ат-Тарика аль-Мухаммадия», 4/326; «Ахкам аль-джанаиз», стр. 321; «Тальхыс аль-Джанаиз», стр. 103.</b>"],["sep",""],["p","ВОПРОС № 14: ЗАВЕЩАНИЕ ДЕНЕГ ДЛЯ ТОГО, ЧТОБЫ ПОСЛЕ СМЕРТИ ЧЕЛОВЕКА ЛЮДИ ЧИТАЛИ ВЕЛИКИЙ КОРАН, СОВЕРШАЛИ ДОПОЛНИТЕЛЬНЫЕ МОЛИТВЫ, ПРОСЛАВЛЯЛИ АЛЛАХА, ПРОСИЛИ БЛАГОСЛОВЕНИЯ ДЛЯ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ), А ЗАТЕМ ДАРИЛИ НАГРАДУ ДУШЕ УМЕРШЕГО ИЛИ ДУШЕ ТОГО, КТО ЕГО НАВЕЩАЕТ"],["p","<b>См. «ат-Тарика аль-Мухаммадия», 4/323; «Ахкам аль-джанаиз», стр. 321; «Тальхыс аль-Джанаиз», стр. 103.</b>"],["sep",""],["p","ВОПРОС № 15: РОДСТВЕННИК УМЕРШЕГО РАЗДАЁТ ЧТО-НИБУДЬ В КАЧЕСТВЕ МИЛОСТЫНИ, ПОКА НЕ ПРОШЛА ПЕРВАЯ НОЧЬ С ЕГО СМЕРТИ. ЕСЛИ ЖЕ ОН НЕ НАХОДИТ ТОГО, ЧТО МОЖНО РАЗДАТЬ, ОН СОВЕРШАЕТ МОЛИТВУ В ДВА РАКААТА И ЧИТАЕТ В КАЖДОМ РАКААТЕ «АЛЬ-ФАТИХУ», «АЯТ АЛЬ-КУРСИЙ» ПО ОДНОМУ РАЗУ, И СУРУ «АТ-ТАКАСУР» ДЕСЯТЬ РАЗ. А ПОСЛЕ ОКОЧАНИЯ МОЛИТВЫ ОН ГОВОРИТ: «О АЛЛАХ! Я СОВЕРШИЛ ЭТУ МОЛИТВУ И ТЫ ЗНАЕШЬ, РАДИ ЧЕГО Я ЕЁ СОВЕРШАЛ. О АЛЛАХ! ОТПРАВЬ НАГРАДУ ЗА НЕЁ К МОГИЛЕ ТАКОГО-ТО УМЕРШЕГО!»."],["p","<b>См. «Ахкам аль-джанаиз», стр. 322; «Тальхыс аль-Джанаиз», стр. 104.</b>"],["sep",""],["h2","ВОПРОС № 16: РАЗДАЧА ОТ ИМЕНИ УМЕРШЕГО В КАЧЕСТВЕ МИЛОСТЫНИ ТОГО, ЧТО ОН ЛЮБИЛ ИЗ ЕДЫ"],["p","<b>См. «Ахкам аль-джанаиз», стр. 322; «Тальхыс аль-Джанаиз», стр. 104.</b>"],["sep",""],["h2","ВОПРОС № 17: РАЗДАЧА МИЛОСТЫНИ ОТ ДУШИ УМЕРШЕГО В ТЕЧЕНИЕ ТРЁХ МЕСЯЦЕВ: РАДЖАБ, ША′БАН И РАМАДАН"]],[["p","<b>См. «Ахкам аль-джанаиз», стр. 322; «Тальхыс аль-Джанаиз», стр. 104.</b>"],["sep",""],["h2","ВОПРОС № 18: ИСКУПЛЕНИЕ ПРОПУЩЕННЫХ МОЛИТВ<sup class=\"fn\">539</sup>"],["n",[[539,"Речь идёт о том, что некоторые ученые сказали, что если умерший пропустил молитвы и не успел возместить их, то его родственники после смерти должны раздать определенное количество милостыни за каждую пропущенную им молитву в качестве искупления. Именно об этом говорится в данном пункте. На подобное искупление нет никакого довода, и поэтому данное мнение является отвергаемым. А Аллах знает лучше!"]]],["p","<b>См. «Ислях аль-масаджид», 281-283; «Ахкам аль-джанаиз», стр. 322; «Тальхыс аль-Джанаиз», стр. 104.</b>"],["sep",""],["h2","ВОПРОС № 19: ЧТЕНИЕ КОРАНА ЗА УМЕРШИХ"],["p","<b>См. «ас-Сунан», 63-65; «Ахкам аль-джанаиз», стр. 322; «Тальхыс аль-Джанаиз», стр. 104.</b>"],["sep",""],["h2","ВОПРОС № 20: «′АТАКА» ЗА УМЕРШЕГО<sup class=\"fn\">540</sup>"],["n",[[540,"Словом «′атака» (<span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">عتاقة</span>) они называют многократное чтение суры «аль-Ихляс» для умершего. Они думают, что это способствует его освобождению от Огня. Но ничего такого нет в Сунне, и поэтому это является новшеством. А Аллах знает лучше!"]]],["p","<b>См. «Ахкам аль-джанаиз», стр. 322; «Тальхыс аль-Джанаиз», стр. 104.</b>"],["sep",""],["h2","ВОПРОС № 21: ПОЛНОЕ ПРОЧТЕНИЕ КОРАНА У МОГИЛЫ УМЕРШЕГО"],["p","<b>См. «Сафар ас-са′ада», 57; «аль-Мадхаль», 1/266-267; «Ахкам аль-джанаиз», стр. 322; «Тальхыс аль-Джанаиз», стр. 104.</b>"],["h3","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «ад-Да′ифа», 1/128, после хадиса № 50:</b>"],["p","«В достоверной Сунне нет ничего, что указывало бы на желательность чтения Корана возле могил. Напротив, Сунна указывает на то, что во время посещения могил узаконено только приветствовать умерших, и само посещение могил узаконено только для того, чтобы вспомнить о Последней жизни. И именно так поступали праведные предшественники (да будет доволен ими Аллах). А чтение Корана возле могил является порицаемым новшеством, как об этом сказала целая группа ранних ученых. Среди них Абу Ханифа, Малик, Ахмад (в одном из мнений от него)."],["p","В книге «Шарх аль-Ихья», 2/285, аз-Забиди сказал: <i>«Это не пришло в Сунне. Мухаммад ибн уль-Хасан и Ахмад (в одной из версий от него) сказали, что это не является порицаемым, так как передаётся, что Ибн ′Умар завещал прочитать на его могиле во время его похорон начало и конец суры \"аль-Бакара\"». </i>"],["p","Я скажу: цепочка передатчиков этого сообщения не является достоверной. И если бы даже она была достоверной, она бы указывала только на чтение Корана во время похорон, а не в любое время, как это очевидно."],["p","О мусульманин! Тебе следует держаться Сунны и остерегаться новшеств, даже если люди считают их благими, ведь каждое новшество является заблуждением, как сказал об этом пророк (да благословит его Аллах и приветствует)»."],["sep",""]]];
